public class Main {
    static int modify(int[] arr, int idx) {
        arr[idx] = arr[idx] * 2;
        return arr[idx] + idx;
    }

    public static void main(String[] args) {
        int[] numbers = {1, 2, 3, 4, 5};
        int sum = 0;

        for (int i = 0; i < numbers.length; i++) {
            if (i % 2 == 0) {
                sum += modify(numbers, i);
            } else {
                sum += numbers[i];
            }
        }

        for (int i = 0; i < numbers.length; i++) {
            System.out.print(numbers[i] + " ");
        }
        System.out.println();
        System.out.println("sum=" + sum);
    }
}

#include <stdio.h>

void update(int *p, int n) {
    for (int i = 0; i < n; i++) {
        p[i] = p[i] + i * 2;
    }
}

int main(void) {
    int arr[5] = {10, 20, 30, 40, 50};
    int *ptr = arr;

    update(ptr, 5);

    int total = 0;
    for (int i = 0; i < 5; i++) {
        total += arr[i];
        printf("%d ", arr[i]);
    }
    printf("\ntotal=%d\n", total);

    return 0;
}

